const SECTORS: { key: string; label: string; icon: (color: string) => React.ReactElement }[] = [
  { key: "Agriculture",  label: "Agriculture", icon: (color) => <SectorAgricultureIcon color={color} /> },
  { key: "Banking",      label: "Banks",       icon: (color) => <SectorBankIcon color={color} /> },
  { key: "Real Estate",  label: "Real Estate", icon: (color) => <SectorRealEstateIcon color={color} /> },
  { key: "Investment",   label: "Investment",  icon: (color) => <SectorInvestmentIcon color={color} /> },
  { key: "Telecommunications", label: "Telecommunication", icon: (color) => <SectorTelecomIcon color={color} /> },
  { key: "Energy",       label: "Energy",      icon: (color) => <SectorEnergyIcon color={color} /> },
  { key: "Finance",      label: "Finance",     icon: (color) => <SectorFinanceIcon color={color} /> },
  { key: "Hospitality",  label: "Hospitality", icon: (color) => <SectorHospitalityIcon color={color} /> },
  { key: "Health",       label: "Health",      icon: (color) => <SectorHealthIcon color={color} /> },
];
const PRIMARY_SECTORS = SECTORS.slice(0, 4);

function SectorsModal({ visible, onClose, getSectorChange, c, isDark }: {
  visible: boolean;
  onClose: () => void;
  getSectorChange: (key: string) => number | null;
  c: Colors;
  isDark: boolean;
}) {
  const [mounted, setMounted] = useState(false);
  const slideY  = useRef(new Animated.Value(SCREEN_H)).current;
  const fadeOvl = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (visible) {
      setMounted(true);
      Animated.parallel([
        Animated.spring(slideY, { toValue: 0, damping: 30, stiffness: 520, mass: 0.6, useNativeDriver: true }),
        Animated.timing(fadeOvl, { toValue: 1, duration: 150, useNativeDriver: true }),
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(slideY, { toValue: SCREEN_H, duration: 260, useNativeDriver: true }),
        Animated.timing(fadeOvl, { toValue: 0, duration: 220, useNativeDriver: true }),
      ]).start(() => setMounted(false));
    }
  }, [visible]);

  // Drag-to-dismiss on the grabber: the sheet follows the finger downward
  // (never above its resting point) and dismisses past a distance/velocity
  // threshold, otherwise springs back.
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: (_evt, g) => Math.abs(g.dy) > 2,
      onPanResponderMove: (_evt, g) => {
        slideY.setValue(Math.max(0, g.dy));
      },
      onPanResponderRelease: (_evt, g) => {
        if (g.dy > 110 || g.vy > 0.8) {
          onClose();
        } else {
          Animated.spring(slideY, { toValue: 0, damping: 24, stiffness: 300, mass: 0.7, useNativeDriver: true }).start();
        }
      },
    }),
  ).current;

  if (!mounted) return null;

  const SECTOR_ICON_BG = c.card;
  const iconColor = isDark ? WHITE : c.primary;

  // Rendered inside the screen's vertical ScrollView, a plain absolute-fill
  // overlay positions against the scrolled content — off-screen once the user
  // has scrolled, which made "View All" look dead. A real Modal always
  // renders at window level.
  return (
    <Modal transparent statusBarTranslucent animationType="none" visible={mounted} onRequestClose={onClose}>
    <View style={[StyleSheet.absoluteFillObject, { zIndex: 999 }]}>
      <View style={{ flex: 1, justifyContent: "flex-end" }}>
        <Animated.View style={[StyleSheet.absoluteFillObject, { backgroundColor: "rgba(0,0,0,0.35)", opacity: fadeOvl }]} pointerEvents={visible ? "auto" : "none"}>
          <TouchableOpacity style={{ flex: 1 }} activeOpacity={1} onPress={onClose} />
        </Animated.View>
        <Animated.View style={[{ backgroundColor: c.background, borderTopLeftRadius: 32, borderTopRightRadius: 32, paddingHorizontal: 24, paddingTop: 14, shadowColor: "#000", shadowOffset: { width: 0, height: -4 }, shadowOpacity: 0.10, shadowRadius: 16, elevation: 24 }, { transform: [{ translateY: slideY }] }]}>
          {/* Grabber — generous touch target; drag down to dismiss */}
          <View {...panResponder.panHandlers} style={{ alignSelf: "stretch", alignItems: "center", paddingVertical: 10, marginTop: -14, marginBottom: 6 }}>
            <View style={{ width: 44, height: 5, borderRadius: 3, backgroundColor: c.border }} />
          </View>
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginBottom: 28 }}>
            <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 18, color: c.text }}>Stock Sectors</Text>
          </View>
          <View style={{ flexDirection: "row", flexWrap: "wrap" }}>
            {SECTORS.map((sector) => {
              const pct = getSectorChange(sector.key);
              const positive = pct !== null && pct >= 0;
              return (
                <TouchableOpacity
                  key={sector.key}
                  activeOpacity={0.75}
                  style={{ width: "33.33%", alignItems: "center", paddingBottom: 28 }}
                  onPress={() => {
                    onClose();
                    guardedPush(() => router.push({ pathname: "/stock-search" as any, params: { sector: sector.key } }));
                  }}
                >
                  <View style={{ width: 64, height: 64, borderRadius: 16, backgroundColor: SECTOR_ICON_BG, alignItems: "center", justifyContent: "center", marginBottom: 10 }}>{sector.icon(iconColor)}</View>
                  <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 12, color: c.text, textAlign: "center", marginBottom: 3 }}>{sector.label}</Text>
                  <Text style={{ fontFamily: "PlusJakartaSans_500Medium", fontSize: 12, textAlign: "center", color: pct === null ? MUTED : positive ? GREEN : RED }}>
                    {pct === null ? "—" : `${positive ? "+" : ""}${pct.toFixed(2)}%`}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
          <View style={{ height: 32 }} />
        </Animated.View>
      </View>
    </View>
    </Modal>
  );
}

function StockLogoSmall({ symbol, c }: { symbol: string; c: Colors }) {
  const logo = getStockLogo(symbol);
  if (logo) {
    return (
      <View style={{ width: 36, height: 36, borderRadius: 18, backgroundColor: c.card, alignItems: "center", justifyContent: "center", overflow: "hidden", borderWidth: 1, borderColor: c.border }}>
        <Image source={logo} style={{ width: 28, height: 28, borderRadius: 14 }} resizeMode="contain" />
      </View>
    );
  }
  const colors = LOGO_COLORS;
  const bg = colors[symbol.charCodeAt(0) % colors.length];
  return (
    <View style={{ width: 36, height: 36, borderRadius: 18, backgroundColor: bg, justifyContent: "center", alignItems: "center" }}>
      <Text style={{ color: "#fff", fontFamily: "PlusJakartaSans_700Bold", fontSize: 9 }}>{symbol.slice(0, 3)}</Text>
    </View>
  );
}

export default function MarketScreen() {
  const insets = useSafeAreaInsets();
  const topPad = Platform.OS === "web" ? 44 : insets.top || 16;
  const c = useColors();
  const { isDark } = useTheme();
  const [showSectors, setShowSectors] = useState(false);
  const [showSearch, setShowSearch] = useState(false);

  // Hide the bottom tab bar while scrolling down; reveal on scroll-up.
  const onScrollHideTabBar = useHideTabBarOnScroll();

  const { data: stocks = [], isLoading, error, refetch, isRefetching } = useStocks();

  const topGainers = useMemo(() => {
    return [...stocks].sort((a, b) => b.changePct - a.changePct).slice(0, 6);
  }, [stocks]);

  const topLosers = useMemo(() => {
    return [...stocks].sort((a, b) => a.changePct - b.changePct).slice(0, 6);
  }, [stocks]);

  const allStocks = stocks;

  const sectorStats = useMemo(() => {
    const map: Record<string, { total: number; count: number }> = {};
    stocks.forEach((s) => {
      const key = (s.sector ?? "").toLowerCase();
      if (!map[key]) map[key] = { total: 0, count: 0 };
      map[key].total += s.changePct;
      map[key].count += 1;
    });
    return map;
  }, [stocks]);

  const getSectorChange = (key: string) => {
    const entry = sectorStats[key.toLowerCase()];
    if (!entry || entry.count === 0) return null;
    return entry.total / entry.count;
  };

  const SECTOR_ICON_BG = c.card;
  const iconColor = isDark ? WHITE : c.primary;

  return (
    <View style={{ flex: 1, backgroundColor: c.background }}>
    {showSearch && <StockSearchOverlay onClose={() => setShowSearch(false)} />}
    <ScrollView
      style={{ flex: 1, paddingTop: topPad }}
      showsVerticalScrollIndicator={false}
      onScroll={onScrollHideTabBar}
      scrollEventThrottle={16}
    >
      {/* Header */}
      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 24, paddingTop: 4, paddingBottom: 12 }}>
        <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 24, color: c.text }}>Market</Text>
        <TouchableOpacity activeOpacity={0.7} onPress={() => setShowSearch(true)} style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: c.card, alignItems: "center", justifyContent: "center" }}>
          <SearchIcon color={c.text} />
        </TouchableOpacity>
      </View>

      {/* Stock Features */}
      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 24, marginTop: 24, marginBottom: 14 }}>
        <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 18, color: c.text }}>Top Gainers</Text>
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ paddingLeft: 24, paddingRight: 8, gap: 12 }}>
        {isLoading ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center" }}>
            <Text style={{ color: MUTED, fontFamily: "PlusJakartaSans_400Regular" }}>Loading market data…</Text>
          </View>
        ) : error ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center" }}>
            <Text style={{ color: RED, fontFamily: "PlusJakartaSans_400Regular" }}>Could not load prices</Text>
          </View>
        ) : topGainers.length === 0 ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center", justifyContent: "center" }}>
            <Text style={{ color: MUTED, fontFamily: "PlusJakartaSans_400Regular", fontSize: 13 }}>No stocks available</Text>
          </View>
        ) : (
          topGainers.map((s, idx) => (
            <TouchableOpacity
              key={s.id}
              style={{ width: 240, height: 134, backgroundColor: c.card, borderRadius: 12, borderWidth: 1, borderColor: c.border, paddingHorizontal: 16, paddingVertical: 14, justifyContent: "space-between" }}
              onPress={() => guardedPush(() => router.push(`/stock/${s.symbol}` as any))}
              activeOpacity={0.85}
            >
              <View style={{ flexDirection: "row", alignItems: "center" }}>
                <StockLogoSmall symbol={s.symbol} c={c} />
                <View style={{ flex: 1, marginLeft: 10 }}>
                  <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 14, color: c.text }}>{s.symbol}</Text>
                  <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 11, color: MUTED, marginTop: 1 }} numberOfLines={1}>{s.name}</Text>
                </View>
              </View>
              <View style={{ flexDirection: "row", alignItems: "flex-end", justifyContent: "space-between" }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 17, color: c.text, marginBottom: 5 }}>{s.price}</Text>
                  <View style={{ flexDirection: "row", alignItems: "center", gap: 5 }}>
                    <ArrowCircle positive={s.positive} />
                    <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 12, color: s.positive ? GREEN : RED }}>
                      {s.changePct > 0 ? "+" : ""}{s.changePct.toFixed(2)}%
                    </Text>
                  </View>
                </View>
                <MiniSparkline positive={s.positive} idx={idx} />
              </View>
            </TouchableOpacity>
          ))
        )}
      </ScrollView>

      {/* Top Losers */}
      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 24, marginTop: 24, marginBottom: 14 }}>
        <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 18, color: c.text }}>Top Losers</Text>
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ paddingLeft: 24, paddingRight: 8, gap: 12 }}>
        {isLoading ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center" }}>
            <Text style={{ color: MUTED, fontFamily: "PlusJakartaSans_400Regular" }}>Loading market data…</Text>
          </View>
        ) : error ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center" }}>
            <Text style={{ color: RED, fontFamily: "PlusJakartaSans_400Regular" }}>Could not load prices</Text>
          </View>
        ) : topLosers.length === 0 ? (
          <View style={{ width: 300, paddingVertical: 24, alignItems: "center", justifyContent: "center" }}>
            <Text style={{ color: MUTED, fontFamily: "PlusJakartaSans_400Regular", fontSize: 13 }}>No stocks available</Text>
          </View>
        ) : (
          topLosers.map((s, idx) => (
            <TouchableOpacity
              key={s.id}
              style={{ width: 240, height: 134, backgroundColor: c.card, borderRadius: 12, borderWidth: 1, borderColor: c.border, paddingHorizontal: 16, paddingVertical: 14, justifyContent: "space-between" }}
              onPress={() => guardedPush(() => router.push(`/stock/${s.symbol}` as any))}
              activeOpacity={0.85}
            >
              <View style={{ flexDirection: "row", alignItems: "center" }}>
                <StockLogoSmall symbol={s.symbol} c={c} />
                <View style={{ flex: 1, marginLeft: 10 }}>
                  <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 14, color: c.text }}>{s.symbol}</Text>
                  <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 11, color: MUTED, marginTop: 1 }} numberOfLines={1}>{s.name}</Text>
                </View>
              </View>
              <View style={{ flexDirection: "row", alignItems: "flex-end", justifyContent: "space-between" }}>
                <View style={{ flex: 1 }}>
                  <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 17, color: c.text, marginBottom: 5 }}>{s.price}</Text>
                  <View style={{ flexDirection: "row", alignItems: "center", gap: 5 }}>
                    <ArrowCircle positive={s.positive} />
                    <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 12, color: s.positive ? GREEN : RED }}>
                      {s.changePct > 0 ? "+" : ""}{s.changePct.toFixed(2)}%
                    </Text>
                  </View>
                </View>
                <MiniSparkline positive={s.positive} idx={idx + 6} />
              </View>
            </TouchableOpacity>
          ))
        )}
      </ScrollView>

      {/* Sector Stocks */}
      <SectorsModal visible={showSectors} onClose={() => setShowSectors(false)} getSectorChange={getSectorChange} c={c} isDark={isDark} />

      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 24, marginTop: 24, marginBottom: 14 }}>
        <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 18, color: c.text }}>Sector Stocks</Text>
        <TouchableOpacity activeOpacity={0.7} onPress={() => setShowSectors(true)}>
          <Text style={{ fontFamily: "PlusJakartaSans_500Medium", fontSize: 13, color: MUTED }}>View All</Text>
        </TouchableOpacity>
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ paddingLeft: 24, paddingRight: 8, gap: 12 }}>
        {PRIMARY_SECTORS.map((sector) => {
          const pct = getSectorChange(sector.key);
          const positive = pct !== null && pct >= 0;
          return (
            <TouchableOpacity
              key={sector.key}
              style={{ alignItems: "center", width: 80 }}
              activeOpacity={0.75}
              onPress={() => guardedPush(() => router.push({ pathname: "/stock-search" as any, params: { sector: sector.key } }))}
            >
              <View style={{ width: 60, height: 60, borderRadius: 14, backgroundColor: SECTOR_ICON_BG, alignItems: "center", justifyContent: "center", marginBottom: 8 }}>{sector.icon(iconColor)}</View>
              <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 12, color: c.text, textAlign: "center", marginBottom: 2 }}>{sector.label}</Text>
              <Text style={{ fontFamily: "PlusJakartaSans_500Medium", fontSize: 11, textAlign: "center", color: pct === null ? MUTED : positive ? GREEN : RED }}>
                {pct === null ? "—" : `${positive ? "+" : ""}${pct.toFixed(2)}%`}
              </Text>
            </TouchableOpacity>
          );
        })}
      </ScrollView>

      {/* All Stocks */}
      <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 24, marginTop: 24, marginBottom: 14 }}>
        <Text style={{ fontFamily: "PlusJakartaSans_700Bold", fontSize: 18, color: c.text }}>All Stocks</Text>
        {isRefetching && <Text style={{ color: MUTED, fontSize: 11, fontFamily: "PlusJakartaSans_400Regular" }}>Refreshing…</Text>}
      </View>

      {isLoading ? (
        Array.from({ length: 6 }).map((_, i) => (
          <View key={i} style={{ flexDirection: "row", alignItems: "center", marginHorizontal: 24, paddingVertical: 14, borderBottomWidth: 1, borderBottomColor: c.border, opacity: 0.4 }}>
            <View style={{ width: 44, height: 44, borderRadius: 22, backgroundColor: c.border }} />
            <View style={{ flex: 1, marginLeft: 12, gap: 6 }}>
              <View style={{ height: 14, width: 60, backgroundColor: c.border, borderRadius: 4 }} />
              <View style={{ height: 11, width: 120, backgroundColor: c.border, borderRadius: 4 }} />
            </View>
          </View>
        ))
      ) : error ? (
        <View style={{ paddingVertical: 48, alignItems: "center" }}>
          <Text style={{ color: RED, fontFamily: "PlusJakartaSans_500Medium" }}>Backend unreachable</Text>
          <Text style={{ color: MUTED, fontFamily: "PlusJakartaSans_400Regular", fontSize: 12, marginTop: 4 }}>Make sure the server is running</Text>
          <TouchableOpacity onPress={() => refetch()} style={{ marginTop: 12, paddingHorizontal: 20, paddingVertical: 8, backgroundColor: c.primary, borderRadius: 8 }}>
            <Text style={{ color: WHITE, fontFamily: "PlusJakartaSans_600SemiBold" }}>Retry</Text>
          </TouchableOpacity>
        </View>
      ) : (
        allStocks.map((s, i) => (
          <TouchableOpacity
            key={s.id}
            style={{ flexDirection: "row", alignItems: "center", marginHorizontal: 24, paddingVertical: 14, borderBottomWidth: i < allStocks.length - 1 ? 1 : 0, borderBottomColor: c.border }}
            onPress={() => guardedPush(() => router.push(`/stock/${s.symbol}` as any))}
            activeOpacity={0.8}
          >
            <StockLogo symbol={s.symbol} c={c} />
            <View style={{ flex: 1, marginLeft: 12 }}>
              <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 15, color: c.text }}>{s.symbol}</Text>
              <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 12, color: MUTED, marginTop: 2 }} numberOfLines={1}>{s.name}</Text>
            </View>
            <View style={{ alignItems: "flex-end" }}>
              <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 15, color: c.text }}>{s.price}</Text>
              <Text style={{ fontFamily: "PlusJakartaSans_500Medium", fontSize: 12, marginTop: 2, color: s.positive ? GREEN : RED }}>{s.change}</Text>
            </View>
          </TouchableOpacity>
        ))
      )}

      <View style={{ height: 32 }} />
    </ScrollView>
    </View>
  );
}

// ─── Stock search overlay ───────────────────────────────────────────────────
function StockSearchOverlay({ onClose }: { onClose: () => void }) {
  const c = useColors();
  const [query, setQuery] = useState("");
  const { data: allStocks = [], isLoading: allLoading } = useStocks();
  const { data: searchResults = [], isLoading: searching } = useStockSearch(query);

  const isQuerying = query.trim().length > 0;
  const displayList = isQuerying ? searchResults : allStocks;
  const isLoading = isQuerying ? searching : allLoading;

  return (
    <SlidePanel onClose={onClose}>
      <View style={{ flex: 1 }}>
        {/* Search bar */}
        <View style={{ flexDirection: "row", alignItems: "center", paddingHorizontal: 20, paddingBottom: 12, gap: 12 }}>
          <TouchableOpacity onPress={onClose} style={{ width: 32, height: 32, alignItems: "center", justifyContent: "center" }}>
            <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
              <Path d="M15 19l-7-7 7-7" stroke={c.text} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
            </Svg>
          </TouchableOpacity>
          <View style={{ flex: 1, height: 48, backgroundColor: c.card, borderRadius: 12, borderWidth: 1, borderColor: c.border, flexDirection: "row", alignItems: "center", paddingHorizontal: 14, gap: 10 }}>
            <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
              <Circle cx={11} cy={11} r={7.5} stroke={query.length > 0 ? c.primary : MUTED} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
              <Path d="M16.5 16.5L20.5 20.5" stroke={query.length > 0 ? c.primary : MUTED} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
            </Svg>
            <TextInput
              style={{ flex: 1, fontFamily: "PlusJakartaSans_400Regular", fontSize: 15, color: c.text, height: "100%" }}
              placeholder="Search stocks…"
              placeholderTextColor={MUTED}
              value={query}
              onChangeText={setQuery}
              returnKeyType="search"
              autoFocus
            />
            {query.length > 0 && (
              <TouchableOpacity onPress={() => setQuery("")}>
                <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
                  <Circle cx={12} cy={12} r={10} fill={MUTED} />
                  <Path d="M15 9L9 15M9 9L15 15" stroke={WHITE} strokeWidth={1.8} strokeLinecap="round" />
                </Svg>
              </TouchableOpacity>
            )}
          </View>
        </View>

        {/* Results */}
        <ScrollView style={{ flex: 1, paddingHorizontal: 24 }} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
          {!isQuerying && (
            <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 16, color: c.text, marginBottom: 12 }}>All MSE Stocks</Text>
          )}
          {isLoading && (
            <View style={{ alignItems: "center", marginTop: 60 }}>
              <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 15, color: MUTED }}>Searching…</Text>
            </View>
          )}
          {!isLoading && isQuerying && displayList.length === 0 && (
            <View style={{ alignItems: "center", marginTop: 60 }}>
              <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 15, color: MUTED }}>No results for "{query}"</Text>
            </View>
          )}
          {!isLoading && displayList.map((s, i) => (
            <TouchableOpacity
              key={s.id}
              style={[
                { flexDirection: "row", alignItems: "center", paddingVertical: 14 },
                i < displayList.length - 1 && { borderBottomWidth: 1, borderBottomColor: c.border },
              ]}
              onPress={() => guardedPush(() => router.push(`/stock/${s.symbol}` as any))}
              activeOpacity={0.8}
            >
              <View style={{ width: 44, height: 44, borderRadius: 22, backgroundColor: c.card, overflow: "hidden", borderWidth: 1, borderColor: c.border, alignItems: "center", justifyContent: "center" }}>
                {getStockLogo(s.symbol) ? (
                  <Image source={getStockLogo(s.symbol)!} style={{ width: 34, height: 34, borderRadius: 17 }} resizeMode="contain" />
                ) : (
                  <View style={{ width: 44, height: 44, backgroundColor: c.primary, justifyContent: "center", alignItems: "center" }}>
                    <Text style={{ color: WHITE, fontFamily: "PlusJakartaSans_700Bold", fontSize: 10 }}>{s.symbol.slice(0, 3)}</Text>
                  </View>
                )}
              </View>
              <View style={{ flex: 1, marginLeft: 12 }}>
                <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 15, color: c.text }}>{s.symbol}</Text>
                <Text style={{ fontFamily: "PlusJakartaSans_400Regular", fontSize: 12, color: MUTED, marginTop: 2 }} numberOfLines={1}>{s.name}</Text>
              </View>
              <View style={{ alignItems: "flex-end", gap: 4 }}>
                <Text style={{ fontFamily: "PlusJakartaSans_600SemiBold", fontSize: 15, color: c.text }}>{s.price}</Text>
                {/* Search results: change % only — no arrow badge (color carries direction) */}
                <Text style={{ fontFamily: "PlusJakartaSans_500Medium", fontSize: 12, color: s.positive ? GREEN : RED }}>{s.change}</Text>
              </View>
            </TouchableOpacity>
          ))}
          <View style={{ height: 32 }} />
        </ScrollView>
      </View>
    </SlidePanel>
  );
}
